package com.pulsesg.support.dto;
import com.pulsesg.support.entity.Ticket; import jakarta.validation.constraints.*; import java.time.Instant;
public final class ApiDtos { private ApiDtos(){} public record AuthRequest(@Email @NotBlank String email,@NotBlank @Size(min=8) String password){} public record RegisterRequest(@NotBlank String fullName,@Email @NotBlank String email,@NotBlank @Size(min=8) String password){} public record AuthResponse(String token,UserResponse user){} public record UserResponse(Long id,String fullName,String email){} public record TicketRequest(@NotBlank String title,@NotBlank String description,@NotNull Ticket.Category category,@NotNull Ticket.Priority priority){} public record TicketUpdate(String title,String description,Ticket.Category category,Ticket.Priority priority,Ticket.Status status){} public record TicketResponse(Long id,String title,String description,String category,String priority,String status,Instant createdAt,Instant updatedAt){} public record MessageRequest(@NotBlank String message){} public record MessageResponse(Long id,String message,Long userId,Instant createdAt){} public record SuggestionResponse(String suggestion){} }
